/**
 * Import the real 2026-cycle federal candidate roster from the FEC API.
 *
 * Source of truth: https://api.open.fec.gov/v1/candidates/
 *
 * Why this exists: the 2026 roster in `candidates` was machine-generated by
 * assuming every incumbent seeks reelection. 526 of 531 rows are
 * is_verified = false, 475 races hold only that assumed incumbent, and 172
 * hold nobody. FEC filings are an authoritative record of who has actually
 * registered to run for federal office, so for senate/house/presidential we
 * can replace an assumption with a filing.
 *
 * Defaults to candidate_status=C -- "statutory candidate", meaning they have
 * crossed the $5,000 receipts-or-expenditures threshold. Status N filers have
 * registered but not crossed it, and include a long tail of paper candidates
 * who never appear on a ballot. Pass --status=C,N to widen.
 *
 * Governors are NOT covered: they file with state agencies, not the FEC. The
 * same is true of every state and local office, so this can never verify the
 * local roster.
 *
 * Nothing is invented. Every row written comes from an FEC response and is
 * stamped with `source` including the cycle and fetch date. The script never
 * deletes and never overwrites a name -- it inserts candidates FEC lists that
 * we lack, and stamps ones we already hold that FEC confirms.
 *
 * Requires migration 025_candidate_source.sql. Responses cache to .fec-cache/
 * so re-runs cost no quota.
 *
 * Usage:
 *   export $(grep -v '^#' .env.local | xargs)
 *   node scripts/import-fec-candidates.mjs                    # dry run, S+H
 *
 * Defaults to S,H because `races` currently holds no presidential race, so
 * --office=P has nothing to attach 29 filings to. Add the race first.
 *   node scripts/import-fec-candidates.mjs --office=S         # senate only
 *   node scripts/import-fec-candidates.mjs --status=C,N       # widen
 *   node scripts/import-fec-candidates.mjs --apply
 */
import { createClient } from '@supabase/supabase-js'
import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { existsSync } from 'node:fs'

const APPLY = process.argv.includes('--apply')
const arg = (n, d) => (process.argv.find((a) => a.startsWith(`--${n}=`)) || `--${n}=${d}`).split('=')[1]
const CYCLE = arg('cycle', '2026')
const OFFICES = arg('office', 'S,H').split(',').map((s) => s.trim().toUpperCase())
const STATUSES = arg('status', 'C').split(',').map((s) => s.trim().toUpperCase())
const MAX_PAGES = Number(arg('max-pages', '60'))

const KEY = process.env.FEC_API_KEY || 'DEMO_KEY'
const CACHE = '.fec-cache'
const OFFICE_CHAMBER = { S: 'senate', H: 'house', P: 'presidential' }
const FETCHED = new Date().toISOString().slice(0, 10)

const sb = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY)

/* ---------- helpers ---------- */

/**
 * FEC ships "MORAN, NATHANIEL QUENTIN". People are not stored that way.
 *
 * Filers also append honorifics to the given-name field -- "ADLAKHA, SARAH
 * ANNE DR", "CLEMENT, CHRISTINA LOREN REV DR TRUSTE" -- which would otherwise
 * be title-cased into the name as if "Dr" were a middle name. Honorifics are
 * dropped; generational suffixes are kept, since they distinguish people.
 */
const HONORIFICS = new Set(['DR', 'MR', 'MRS', 'MS', 'MISS', 'REV', 'HON', 'PROF', 'SGT', 'CAPT', 'TRUSTE'])
const SUFFIXES = new Set(['JR', 'SR', 'II', 'III', 'IV', 'V'])

function properName(fecName) {
  const raw = String(fecName || '').trim()
  if (!raw) return ''
  const [last, rest] = raw.includes(',') ? [raw.slice(0, raw.indexOf(',')), raw.slice(raw.indexOf(',') + 1)] : ['', raw]

  // Pull suffixes and honorifics out of the given-name side before reordering,
  // so a suffix lands after the surname and an honorific vanishes.
  const givenTokens = []
  const suffixTokens = []
  for (const tok of (rest || raw).trim().split(/\s+/).filter(Boolean)) {
    const bare = tok.replace(/[.,]/g, '').toUpperCase()
    if (HONORIFICS.has(bare)) continue
    if (SUFFIXES.has(bare)) { suffixTokens.push(bare); continue }
    givenTokens.push(tok)
  }

  const surname = last.trim()
  const ordered = [givenTokens.join(' '), surname, suffixTokens.join(' ')].filter(Boolean).join(' ')
  if (!ordered.trim()) return raw

  return ordered
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map((w) =>
      w
        .split(/([-'])/)
        .map((part) => (part === '-' || part === "'" ? part : part.charAt(0).toUpperCase() + part.slice(1)))
        .join('')
    )
    .join(' ')
    .replace(/\bMc([a-z])/g, (_, c) => `Mc${c.toUpperCase()}`)
    .replace(/\b(Ii|Iii|Iv|V)\b$/, (m) => m.toUpperCase())
    .replace(/\b(Jr|Sr)\b$/, (m) => `${m}.`)
    .trim()
}

/** party_type only has four values, so everything else is independent. */
const PARTY = { DEM: 'democrat', REP: 'republican', GRE: 'green', GRN: 'green' }
const toParty = (p) => PARTY[String(p || '').toUpperCase()] ?? 'independent'

const norm = (s) =>
  (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/\b(jr|sr|ii|iii|iv|dr|mr|mrs|ms)\b\.?/g, '')
    .replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim()

/**
 * Normalise a district for keying. Chamber-aware, because the two sides encode
 * at-large seats differently: FEC sends "00" for a state with a single
 * House seat, our races store "AL". Treating "00" as null silently orphaned
 * every candidate in DE, ND, SD, VT, WY and AK.
 */
const undistrict = (d, chamber) => {
  const s = String(d ?? '').trim().toUpperCase()
  if (chamber !== 'house') return null // senate and presidential have no district
  if (!s || s === '00' || s === 'AL') return 'AL'
  return s.replace(/^0+/, '') || 'AL'
}

async function fecPage(office, status, page) {
  if (!existsSync(CACHE)) await mkdir(CACHE, { recursive: true })
  const f = `${CACHE}/cands-${CYCLE}-${office}-${status}-p${page}.json`
  if (existsSync(f)) return JSON.parse(await readFile(f, 'utf8'))

  const url =
    `https://api.open.fec.gov/v1/candidates/?api_key=${KEY}` +
    `&election_year=${CYCLE}&office=${office}&candidate_status=${status}` +
    `&per_page=100&page=${page}&sort=name`
  const resp = await fetch(url)
  if (!resp.ok) {
    throw new Error(`FEC HTTP ${resp.status} (${office}/${status} p${page}): ${(await resp.text()).slice(0, 200)}`)
  }
  const json = await resp.json()
  await writeFile(f, JSON.stringify(json))
  console.log(`   fetched ${office}/${status} page ${page} (rate-limit remaining: ${resp.headers.get('x-ratelimit-remaining') ?? 'n/a'})`)
  return json
}

async function pageAll(table, cols, tweak = (q) => q) {
  const out = []
  for (let from = 0; ; from += 1000) {
    const { data, error } = await tweak(sb.from(table).select(cols)).range(from, from + 999)
    if (error) throw new Error(`${table}: ${error.message}`)
    out.push(...data)
    if (data.length < 1000) break
  }
  return out
}

/* ---------- go ---------- */

console.log(`\n${APPLY ? '*** APPLYING ***' : '--- DRY RUN (pass --apply to write) ---'}`)
console.log(`cycle ${CYCLE} · offices ${OFFICES.join(',')} · status ${STATUSES.join(',')}\n`)

// `source` is required to stamp provenance; refuse to write without it.
const { error: probeErr } = await sb.from('candidates').select('source').limit(1)
const hasSource = !probeErr
if (!hasSource) {
  console.log('! candidates.source is missing — run supabase/migrations/025_candidate_source.sql')
  if (APPLY) {
    console.log('  refusing to write unsourced rows. Exiting.')
    process.exit(1)
  }
  console.log('  (dry run continues; --apply will refuse until the migration is run)\n')
}

const fecRows = []
for (const office of OFFICES) {
  for (const status of STATUSES) {
    for (let p = 1; p <= MAX_PAGES; p++) {
      const json = await fecPage(office, status, p)
      const results = json.results ?? []
      for (const r of results) {
        fecRows.push({
          office,
          chamber: OFFICE_CHAMBER[office],
          state: r.state,
          district: undistrict(r.district, OFFICE_CHAMBER[office]),
          name: properName(r.name),
          party: toParty(r.party),
          isIncumbent: r.incumbent_challenge === 'I',
          fecId: r.candidate_id,
          status,
        })
      }
      const pages = json.pagination?.pages ?? 1
      if (p >= pages || results.length === 0) break
    }
  }
}
console.log(`\nFEC returned ${fecRows.length} candidate filings`)

const races = await pageAll('races', 'id,name,state,chamber,district', (q) =>
  q.in('chamber', OFFICES.map((o) => OFFICE_CHAMBER[o]))
)
const raceKey = (state, chamber, district) => `${state}|${chamber}|${undistrict(district, chamber) ?? ''}`
const raceIdx = new Map()
for (const r of races) raceIdx.set(raceKey(r.state, r.chamber, r.district), r)

const existing = await pageAll('candidates', 'id,race_id,name,party,is_incumbent,is_verified')
const byRace = new Map()
for (const c of existing) {
  if (!byRace.has(c.race_id)) byRace.set(c.race_id, [])
  byRace.get(c.race_id).push(c)
}

const toInsert = []
const toStamp = []
let unmatchedRace = 0
const unmatchedSample = []

for (const f of fecRows) {
  const race = raceIdx.get(`${f.state}|${f.chamber}|${f.district ?? ''}`)
  if (!race) {
    unmatchedRace++
    if (unmatchedSample.length < 6) unmatchedSample.push(`${f.state} ${f.chamber} ${f.district ?? '-'} ${f.name}`)
    continue
  }
  const mine = byRace.get(race.id) ?? []
  const hit = mine.find((c) => norm(c.name) === norm(f.name))
  if (hit) {
    if (!hit.is_verified) toStamp.push({ id: hit.id, fec: f, race })
  } else {
    toInsert.push({ fec: f, race })
  }
}

const racesTouched = new Set([...toInsert.map((r) => r.race.id), ...toStamp.map((r) => r.race.id)])
console.log(`\nmatched to one of our ${races.length} races:`)
console.log(`  already held, FEC confirms  ${toStamp.length}   -> stamp is_verified + source`)
console.log(`  FEC has, we lack            ${toInsert.length}   -> insert`)
console.log(`  no matching race in our db  ${unmatchedRace}`)
for (const u of unmatchedSample) console.log(`     e.g. ${u}`)
console.log(`  distinct races affected     ${racesTouched.size}`)

const emptyBefore = races.filter((r) => !(byRace.get(r.id) ?? []).length).length
const emptyAfter = races.filter(
  (r) => !(byRace.get(r.id) ?? []).length && !toInsert.some((t) => t.race.id === r.id)
).length
console.log(`  federal races with zero candidates: ${emptyBefore} -> ${emptyAfter}`)

if (!APPLY) {
  console.log('\nsample inserts:')
  for (const t of toInsert.slice(0, 8)) {
    console.log(`  ${t.race.name}: ${t.fec.name} (${t.fec.party}${t.fec.isIncumbent ? ', incumbent' : ''})`)
  }
  process.exit(0)
}

const SOURCE = `FEC API (candidates, cycle ${CYCLE}, status ${STATUSES.join('+')}, fetched ${FETCHED})`

let inserted = 0
for (let i = 0; i < toInsert.length; i += 200) {
  const chunk = toInsert.slice(i, i + 200).map(({ fec, race }) => ({
    race_id: race.id,
    name: fec.name,
    party: fec.party,
    is_incumbent: fec.isIncumbent,
    status: 'running',
    is_verified: true,
    last_checked: new Date().toISOString(),
    source: SOURCE,
  }))
  const { error } = await sb.from('candidates').insert(chunk)
  if (error) console.log(`  ! insert batch ${i / 200}: ${error.message}`)
  else inserted += chunk.length
}

let stamped = 0
for (const { id } of toStamp) {
  const { error } = await sb
    .from('candidates')
    .update({ is_verified: true, last_checked: new Date().toISOString(), source: SOURCE })
    .eq('id', id)
  if (error) console.log(`  ! stamp ${id}: ${error.message}`)
  else stamped++
}

console.log(`\n=> inserted ${inserted}, stamped ${stamped}`)
